import { EgradxApiError } from '@babulvaibhav/egradx-client'

/*
 * Shared by the EGRADX recipes (shadcn registry items from @babulvaibhav/egradx-ui). Copied into your project like the rest of
 * a recipe: change the wording, the formats or the colours here and every recipe follows.
 */

/** Something to tell the person: wire it to your toasts (`sonner`'s `toast[tone](title, { description })`). */
export type Notify = (message: { tone: 'success' | 'info' | 'warning' | 'error'; title: string; description?: string }) => void

/** Used when a recipe is given no `onNotify`: messages are dropped, the screens still show errors inline. */
export const ignoreNotice: Notify = () => {}

/** Badge colours by meaning, for `<Badge variant="outline" className={tone.success}>`. */
export const tone = {
  success: 'border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  warning: 'border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-400',
  info: 'border-sky-500/30 bg-sky-500/10 text-sky-700 dark:text-sky-400',
  danger: 'border-destructive/30 bg-destructive/10 text-destructive',
  muted: 'text-muted-foreground',
} as const

const dateTime = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' })
const relative = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' })

export function formatDateTime(iso: string | null | undefined): string {
  return iso ? dateTime.format(new Date(iso)) : '—'
}

/** "3 minutes ago", "in 2 hours". */
export function formatRelative(iso: string | null | undefined): string {
  if (!iso) return '—'
  const seconds = (new Date(iso).getTime() - Date.now()) / 1000
  const units: [Intl.RelativeTimeFormatUnit, number][] = [['year', 31536000], ['month', 2592000], ['day', 86400], ['hour', 3600], ['minute', 60]]
  for (const [unit, size] of units) {
    if (Math.abs(seconds) >= size) return relative.format(Math.round(seconds / size), unit)
  }
  return relative.format(Math.round(seconds), 'second')
}

/** `oim.product_updated` → "Oim product updated". */
export function humanize(value: string | null | undefined): string {
  if (!value) return ''
  const words = value.replace(/[._-]+/g, ' ').trim().toLowerCase()
  return words.charAt(0).toUpperCase() + words.slice(1)
}

export function shortId(id: string): string {
  return id.slice(0, 8)
}

/** A channel id as people read it. Unknown ids, added by configuration, are shown as they are. */
export function channelLabel(id: string): string {
  const labels: Record<string, string> = { email: 'Email', sms: 'SMS', whatsapp: 'WhatsApp', slack: 'Slack', webhook: 'Webhook', log: 'Log' }
  return labels[id] ?? id
}

/** What went wrong, to show the person: the server's message, or a plain one. */
export function errorText(error: unknown): string {
  if (error instanceof EgradxApiError) {
    if (error.code === 'NETWORK_ERROR') return 'The server could not be reached. Check your connection and try again.'
    if (error.code === 'ACCESS_DENIED') return 'You do not have permission to do this.'
    return error.message
  }
  return error instanceof Error ? error.message : 'Something went wrong.'
}

export function errorCode(error: unknown): string | undefined {
  return error instanceof EgradxApiError ? error.code : undefined
}

'use client'

import { useEffect, useState, type ReactNode } from 'react'
import { Inbox, LoaderCircle, RefreshCw, Search, ShieldAlert, TriangleAlert, X } from 'lucide-react'
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { errorCode, errorText } from './egradx-ui'

/* The small pieces every EGRADX recipe shares: empty and error states, a confirmation, a search box. */

interface StateProps {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  action?: ReactNode
  className?: string
}

export function EmptyState({ icon = <Inbox />, title, description, action, className }: StateProps) {
  return (
    <div className={cn('flex flex-col items-center justify-center gap-3 px-6 py-12 text-center', className)}>
      <div className="bg-muted text-muted-foreground flex size-12 items-center justify-center rounded-full [&_svg]:size-5">{icon}</div>
      <div className="space-y-1">
        <p className="font-medium">{title}</p>
        {description && <p className="text-muted-foreground mx-auto max-w-sm text-sm">{description}</p>}
      </div>
      {action}
    </div>
  )
}

/** A failed load: "not allowed" for a refusal, otherwise what went wrong, with a retry. */
export function ErrorState({ error, onRetry, className }: { error: unknown; onRetry?: () => void; className?: string }) {
  if (errorCode(error) === 'ACCESS_DENIED') {
    return (
      <EmptyState
        className={className}
        icon={<ShieldAlert />}
        title="Access restricted"
        description="Your role does not include this. Ask an administrator if you need it."
      />
    )
  }
  return (
    <EmptyState
      className={className}
      icon={<TriangleAlert className="text-destructive" />}
      title="Couldn't load this"
      description={errorText(error)}
      action={
        onRetry && (
          <Button variant="outline" size="sm" onClick={onRetry}>
            <RefreshCw /> Try again
          </Button>
        )
      }
    />
  )
}

interface ConfirmDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: ReactNode
  description?: ReactNode
  confirmLabel?: string
  destructive?: boolean
  pending?: boolean
  onConfirm: () => void
}

/** Asks before something that cannot be undone; stays open until the change is done. */
export function ConfirmDialog({ open, onOpenChange, title, description, confirmLabel = 'Confirm', destructive, pending, onConfirm }: ConfirmDialogProps) {
  return (
    <AlertDialog open={open} onOpenChange={(next) => !pending && onOpenChange(next)}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description && <AlertDialogDescription>{description}</AlertDialogDescription>}
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>Cancel</AlertDialogCancel>
          <Button variant={destructive ? 'destructive' : 'default'} disabled={pending} onClick={onConfirm}>
            {pending && <LoaderCircle className="animate-spin" />}
            {confirmLabel}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

/** A search box that reports what was typed once typing pauses. */
export function SearchBox({ value, onChange, placeholder = 'Search…', className }: { value: string; onChange: (value: string) => void; placeholder?: string; className?: string }) {
  const [draft, setDraft] = useState(value)
  useEffect(() => setDraft(value), [value])
  useEffect(() => {
    if (draft.trim() === value) return
    const timer = setTimeout(() => onChange(draft.trim()), 300)
    return () => clearTimeout(timer)
    // Only typing starts the timer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft])
  return (
    <div className={cn('relative w-full sm:w-72', className)}>
      <Search className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2" />
      <Input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder={placeholder} aria-label={placeholder} className="pr-8 pl-9" />
      {draft && (
        <button
          type="button"
          onClick={() => setDraft('')}
          className="text-muted-foreground hover:text-foreground absolute top-1/2 right-2 -translate-y-1/2 rounded p-0.5"
          aria-label="Clear search"
        >
          <X className="size-3.5" />
        </button>
      )}
    </div>
  )
}

'use client'

import { useState, type FormEvent } from 'react'
import type { Contact, Contacts, ProfileOptions } from '@babulvaibhav/egradx-client'
import { useAction } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { channelLabel, errorText } from '../egradx-ui'

interface AddContactDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  options: ProfileOptions
  /** Adds the address and reloads the list it shows in. */
  add: Contacts['add']
  /** Called with the new, unverified contact: to go straight on to verifying it. */
  onAdded: (contact: Contact) => void
}

/** A new address for the person, on one of the channels that take contacts. It starts unverified. */
export function AddContactDialog({ open, onOpenChange, options, add, onAdded }: AddContactDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Add an address</DialogTitle>
          <DialogDescription>Where messages on this channel should reach you. You'll verify it next.</DialogDescription>
        </DialogHeader>
        {/* Mounted while open, so every opening starts from an empty form. */}
        {open && <ContactForm options={options} add={add} onDone={(contact) => (onOpenChange(false), onAdded(contact))} onCancel={() => onOpenChange(false)} />}
      </DialogContent>
    </Dialog>
  )
}

function ContactForm({ options, add, onDone, onCancel }: { options: ProfileOptions; add: Contacts['add']; onDone: (contact: Contact) => void; onCancel: () => void }) {
  const [channel, setChannel] = useState(options.channels[0]?.id ?? 'email')
  const [address, setAddress] = useState('')
  const [label, setLabel] = useState('')
  // A Slack member id belongs to one workspace, so it applies in this organization only.
  const [organizationScoped, setOrganizationScoped] = useState(channel === 'slack')
  const format = options.channels.find((option) => option.id === channel)?.addressFormat
  const save = useAction(async () => {
    const contact = await add({ channel, address: address.trim(), label: label.trim() || null, organizationScoped, primary: false, verified: false })
    onDone(contact)
  })

  const submit = (event: FormEvent) => {
    event.preventDefault()
    if (address.trim()) void save.run().catch(() => {})
  }

  return (
    <form className="space-y-4" onSubmit={submit}>
      <div className="space-y-2">
        <Label htmlFor="contact-channel">Channel</Label>
        <Select
          value={channel}
          onValueChange={(next) => {
            setChannel(next)
            setOrganizationScoped(next === 'slack')
          }}
        >
          <SelectTrigger id="contact-channel" className="w-full">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {options.channels.map((option) => (
              <SelectItem key={option.id} value={option.id}>
                {channelLabel(option.id)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="space-y-2">
        <Label htmlFor="contact-address">Address</Label>
        <Input id="contact-address" autoComplete="off" required maxLength={512} value={address} onChange={(event) => setAddress(event.target.value)} />
        {format && <p className="text-muted-foreground text-xs">{format}</p>}
      </div>
      <div className="space-y-2">
        <Label htmlFor="contact-label">
          Label <span className="text-muted-foreground font-normal">(optional)</span>
        </Label>
        <Input id="contact-label" placeholder="e.g. work" maxLength={100} value={label} onChange={(event) => setLabel(event.target.value)} />
      </div>
      <label className="flex items-center gap-2 text-sm">
        <Checkbox checked={organizationScoped} onCheckedChange={(checked) => setOrganizationScoped(checked === true)} />
        Only for this organization
      </label>
      {save.error && (
        <p className="text-destructive text-sm" role="alert">
          {errorText(save.error)}
        </p>
      )}
      <DialogFooter>
        <Button type="button" variant="outline" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit" disabled={save.pending || !address.trim()}>
          {save.pending ? 'Adding…' : 'Add address'}
        </Button>
      </DialogFooter>
    </form>
  )
}

'use client'

import { useEffect, useState } from 'react'
import type { Contact, Contacts, VerificationStarted } from '@babulvaibhav/egradx-client'
import { useAction } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { channelLabel, errorCode, errorText, formatRelative, ignoreNotice, type Notify } from '../egradx-ui'

interface VerifyContactDialogProps {
  contact: Contact | null
  /** The list the contact is in: confirming reloads it. */
  contacts: Pick<Contacts, 'startVerification' | 'confirmVerification' | 'reload'>
  onOpenChange: (open: boolean) => void
  onNotify?: Notify
}

/**
 * Sends a six-digit code through the channel being verified, then confirms it. Key it by the contact
 * (`key={contact?.id}`) so each one starts afresh.
 */
export function VerifyContactDialog({ contact, contacts, onOpenChange, onNotify = ignoreNotice }: VerifyContactDialogProps) {
  const [started, setStarted] = useState<VerificationStarted | null>(null)
  const [code, setCode] = useState('')
  const [now, setNow] = useState(() => Date.now())

  // Re-renders once a second while waiting, so "Resend" enables itself when it may.
  useEffect(() => {
    if (!started) return
    const timer = setInterval(() => setNow(Date.now()), 1000)
    return () => clearInterval(timer)
  }, [started])

  const send = useAction(async () => {
    setStarted(await contacts.startVerification(contact!.id))
    setCode('')
    setNow(Date.now())
  })
  const confirm = useAction(async () => {
    try {
      await contacts.confirmVerification(contact!.id, code.trim())
    } catch (error) {
      const reason = errorCode(error)
      // A used-up or expired code means starting again; the message says why.
      if (reason === 'CONTACT_VERIFICATION_EXPIRED' || reason === 'CONTACT_VERIFICATION_TOO_MANY_ATTEMPTS') setStarted(null)
      if (reason === 'CONTACT_ALREADY_VERIFIED') {
        void contacts.reload()
        onOpenChange(false)
      }
      throw error
    }
    onNotify({ tone: 'success', title: 'Address verified', description: contact?.address })
    onOpenChange(false)
  })

  const canResend = !!started && now >= Date.parse(started.resendAvailableAt)
  const error = send.error ?? confirm.error

  return (
    <Dialog open={!!contact} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Verify {contact ? channelLabel(contact.channel) : ''} address</DialogTitle>
          <DialogDescription>
            {started
              ? `Enter the code sent to ${started.address}. It expires ${formatRelative(started.expiresAt)}.`
              : `We'll send a six-digit code to ${contact?.address ?? ''}. Only a verified address receives messages.`}
          </DialogDescription>
        </DialogHeader>

        {started && (
          <div className="space-y-2">
            <Label htmlFor="verification-code">Code</Label>
            <Input
              id="verification-code"
              inputMode="numeric"
              autoComplete="one-time-code"
              maxLength={6}
              placeholder="123456"
              value={code}
              onChange={(event) => setCode(event.target.value.replace(/\D/g, ''))}
            />
          </div>
        )}

        {error && (
          <p className="text-destructive text-sm" role="alert">
            {errorText(error)}
            {errorCode(error) === 'CONTACT_VERIFICATION_UNAVAILABLE' && ' If this channel is not set up for your organization yet, ask an administrator.'}
          </p>
        )}

        <DialogFooter>
          {started ? (
            <>
              <Button variant="outline" onClick={() => void send.run().catch(() => {})} disabled={!canResend || send.pending}>
                {canResend ? 'Resend code' : 'Code sent'}
              </Button>
              <Button onClick={() => void confirm.run().catch(() => {})} disabled={code.trim().length !== 6 || confirm.pending}>
                {confirm.pending ? 'Checking…' : 'Verify'}
              </Button>
            </>
          ) : (
            <Button onClick={() => void send.run().catch(() => {})} disabled={send.pending}>
              {send.pending ? 'Sending…' : 'Send code'}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import { Plus, Star, Trash2 } from 'lucide-react'
import type { Contact } from '@babulvaibhav/egradx-client'
import { useAction, useContacts } from '@babulvaibhav/egradx-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardAction, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { ConfirmDialog, ErrorState } from '../egradx-common'
import { channelLabel, errorText, ignoreNotice, tone, type Notify } from '../egradx-ui'
import { AddContactDialog } from './add-contact-dialog'
import { VerifyContactDialog } from './verify-contact-dialog'

/**
 * Where messages outside the app reach the person. Only a verified address is ever used, since one typed but never
 * confirmed could belong to anyone; email also falls back to the address they sign in with.
 */
export function ContactsCard({ signInEmail, onNotify = ignoreNotice }: { signInEmail?: string; onNotify?: Notify }) {
  const contacts = useContacts()
  const options = contacts.data?.options
  const [adding, setAdding] = useState(false)
  const [verifying, setVerifying] = useState<Contact | null>(null)
  const [removing, setRemoving] = useState<Contact | null>(null)

  const makePrimary = useAction(async (id: string) => {
    try {
      await contacts.makePrimary(id)
    } catch (error) {
      onNotify({ tone: 'error', title: 'Could not change the primary address', description: errorText(error) })
    }
  })
  const remove = useAction(async (id: string) => {
    try {
      await contacts.remove(id)
      setRemoving(null)
    } catch (error) {
      onNotify({ tone: 'error', title: 'Could not remove the address', description: errorText(error) })
    }
  })

  return (
    <Card>
      <CardHeader>
        <CardTitle>Where we reach you</CardTitle>
        <CardDescription>
          Messages outside the app go only to verified addresses.
          {signInEmail && ` Email goes to your sign-in address (${signInEmail}) unless you add and verify another.`}
        </CardDescription>
        {options && (
          <CardAction>
            <Button size="sm" onClick={() => setAdding(true)}>
              <Plus /> Add address
            </Button>
          </CardAction>
        )}
      </CardHeader>
      <CardContent className="space-y-5">
        {contacts.loading ? (
          <div className="space-y-2">
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-10 w-full" />
          </div>
        ) : !contacts.data ? (
          <ErrorState error={contacts.error} onRetry={() => void contacts.reload()} />
        ) : (
          contacts.data.options.channels.map((channel) => {
            const onChannel = contacts.data!.contacts.filter((contact) => contact.channel === channel.id)
            const reachable = onChannel.some((contact) => contact.verified) || channel.id === 'email'
            return (
              <div key={channel.id} className="space-y-2">
                <div className="flex items-center justify-between">
                  <p className="text-sm font-medium">{channelLabel(channel.id)}</p>
                  {!reachable && <span className="text-muted-foreground text-xs">No verified address — nothing will be sent here.</span>}
                </div>
                {onChannel.length === 0 ? (
                  <p className="text-muted-foreground text-xs">{channel.addressFormat}</p>
                ) : (
                  <ul className="divide-y rounded-md border">
                    {onChannel.map((contact) => (
                      <li key={contact.id} className="flex flex-wrap items-center gap-2 px-3 py-2">
                        <span className="font-mono text-sm">{contact.address}</span>
                        {contact.label && <span className="text-muted-foreground text-xs">{contact.label}</span>}
                        {contact.primary && (
                          <Badge variant="outline" className={tone.info}>
                            Primary
                          </Badge>
                        )}
                        <Badge variant="outline" className={contact.verified ? tone.success : tone.warning}>
                          {contact.verified ? 'Verified' : 'Unverified'}
                        </Badge>
                        {contact.organizationId && <Badge variant="secondary">This organization</Badge>}
                        <div className="ml-auto flex gap-1">
                          {!contact.verified && options!.verificationAvailable && (
                            <Button size="sm" variant="outline" onClick={() => setVerifying(contact)}>
                              Verify
                            </Button>
                          )}
                          {!contact.primary && (
                            <Button size="sm" variant="ghost" onClick={() => void makePrimary.run(contact.id)} disabled={makePrimary.pending}>
                              <Star /> Make primary
                            </Button>
                          )}
                          <Button size="icon" variant="ghost" aria-label="Remove" onClick={() => setRemoving(contact)}>
                            <Trash2 />
                          </Button>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            )
          })
        )}
        {options && !options.verificationAvailable && (
          <p className="text-muted-foreground text-xs">Addresses can't be verified by code here; ask an administrator.</p>
        )}
      </CardContent>

      {options && (
        <AddContactDialog
          open={adding}
          onOpenChange={setAdding}
          options={options}
          add={contacts.add}
          onAdded={(contact) => options.verificationAvailable && setVerifying(contact)}
        />
      )}
      <VerifyContactDialog
        key={verifying?.id ?? 'none'}
        contact={verifying}
        contacts={contacts}
        onOpenChange={(open) => !open && setVerifying(null)}
        onNotify={onNotify}
      />
      <ConfirmDialog
        open={!!removing}
        onOpenChange={(open) => !open && setRemoving(null)}
        title="Remove this address?"
        description={removing ? `${channelLabel(removing.channel)}: ${removing.address}` : undefined}
        confirmLabel="Remove"
        destructive
        pending={remove.pending}
        onConfirm={() => removing && void remove.run(removing.id)}
      />
    </Card>
  )
}

'use client'

import { useMemo, useState } from 'react'
import type { CommunicationPreference, NotificationPreferences, PreferenceOptions } from '@babulvaibhav/egradx-client'
import { useAction, useNotificationPreferences } from '@babulvaibhav/egradx-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { Checkbox } from '@/components/ui/checkbox'
import { Skeleton } from '@/components/ui/skeleton'
import { EmptyState, ErrorState } from '../egradx-common'
import { channelLabel, errorText, ignoreNotice, type Notify } from '../egradx-ui'

/** `null` is "every kind of message" on the channel. */
type Row = string | null
const cell = (channel: string, key: Row) => `${channel}|${key ?? '*'}`

/**
 * Opt-outs, per channel and kind of message. Only kinds the application declared may be declined appear: a password
 * reset is sent whatever anyone chooses. They never affect the in-app inbox.
 */
export function PreferencesMatrix({ onNotify = ignoreNotice }: { onNotify?: Notify }) {
  const preferences = useNotificationPreferences()
  const data = preferences.data

  return (
    <Card>
      <CardHeader>
        <CardTitle>What you receive</CardTitle>
        <CardDescription>Turn off kinds of message on a channel. The in-app notifications always show everything.</CardDescription>
      </CardHeader>
      {preferences.loading ? (
        <CardContent>
          <Skeleton className="h-32 w-full" />
        </CardContent>
      ) : !data ? (
        <CardContent>
          <ErrorState error={preferences.error} onRetry={() => void preferences.reload()} />
        </CardContent>
      ) : data.options.types.length === 0 ? (
        <CardContent>
          <EmptyState title="Nothing to opt out of yet" description="No message sent here can be turned off." />
        </CardContent>
      ) : (
        // Keyed on what is stored, so the form starts again from it after every save.
        <Matrix key={JSON.stringify(data.preferences)} options={data.options} stored={data.preferences} save={preferences.save} onNotify={onNotify} />
      )}
    </Card>
  )
}

function Matrix({ options, stored, save: store, onNotify }: { options: PreferenceOptions; stored: CommunicationPreference[]; save: NotificationPreferences['save']; onNotify: Notify }) {
  const rows: Row[] = [null, ...options.types.map((type) => type.key)]
  const everywhere = useMemo(() => stored.filter((preference) => !preference.organizationScoped), [stored])
  const organizationOnly = useMemo(() => stored.filter((preference) => preference.organizationScoped), [stored])

  // What each box shows: the kind's own setting, else the channel's "every kind", else on.
  const initial = useMemo(() => {
    const find = (channel: string, key: Row) => everywhere.find((preference) => preference.channel === channel && preference.notificationKey === key)?.enabled
    const values: Record<string, boolean> = {}
    for (const channel of options.channels) {
      const all = find(channel, null) ?? true
      values[cell(channel, null)] = all
      for (const type of options.types) values[cell(channel, type.key)] = find(channel, type.key) ?? all
    }
    return values
  }, [everywhere, options])
  const [values, setValues] = useState(initial)
  const dirty = Object.keys(values).some((name) => values[name] !== initial[name])

  // Only what differs from the default is stored: "every kind" when off, and a kind when it differs from its
  // channel's "every kind". Organization-specific rows are sent back as they were: a save replaces both scopes.
  const save = useAction(async () => {
    const preferences: CommunicationPreference[] = [...organizationOnly]
    for (const channel of options.channels) {
      const all = values[cell(channel, null)]
      if (!all) preferences.push({ channel, notificationKey: null, enabled: false, organizationScoped: false })
      for (const type of options.types) {
        const value = values[cell(channel, type.key)]!
        if (value !== all) preferences.push({ channel, notificationKey: type.key, enabled: value, organizationScoped: false })
      }
    }
    try {
      await store(preferences)
      onNotify({ tone: 'success', title: 'Notification settings saved' })
    } catch (error) {
      onNotify({ tone: 'error', title: 'Could not save', description: errorText(error) })
    }
  })

  const toggle = (channel: string, key: Row, checked: boolean) =>
    setValues((previous) => {
      const next = { ...previous, [cell(channel, key)]: checked }
      // Changing "every kind" moves the kinds that were following it.
      if (key === null) {
        for (const type of options.types) {
          if (previous[cell(channel, type.key)] === previous[cell(channel, null)]) next[cell(channel, type.key)] = checked
        }
      }
      return next
    })

  return (
    <>
      <CardContent className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-muted-foreground text-left text-xs">
              <th className="py-2 pr-4 font-medium">Kind of message</th>
              {options.channels.map((channel) => (
                <th key={channel} className="px-3 py-2 text-center font-medium">
                  {channelLabel(channel)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y">
            {rows.map((key) => (
              <tr key={key ?? '*'}>
                <td className="py-2 pr-4">
                  {key === null ? <span className="font-medium">Every kind of message</span> : (options.types.find((type) => type.key === key)?.description ?? key)}
                </td>
                {options.channels.map((channel) => (
                  <td key={channel} className="px-3 py-2 text-center">
                    <Checkbox
                      aria-label={`${channelLabel(channel)}: ${key ?? 'every kind'}`}
                      checked={values[cell(channel, key)]}
                      onCheckedChange={(checked) => toggle(channel, key, checked === true)}
                    />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
        {organizationOnly.length > 0 && (
          <p className="text-muted-foreground mt-3 text-xs">{organizationOnly.length} setting(s) specific to this organization are kept as they are.</p>
        )}
      </CardContent>
      <CardFooter className="justify-end gap-2">
        <Button variant="outline" onClick={() => setValues(initial)} disabled={!dirty || save.pending}>
          Reset
        </Button>
        <Button onClick={() => void save.run()} disabled={!dirty || save.pending}>
          {save.pending ? 'Saving…' : 'Save'}
        </Button>
      </CardFooter>
    </>
  )
}

'use client'

import { ignoreNotice, type Notify } from '../egradx-ui'
import { ContactsCard } from './contacts-card'
import { PreferencesMatrix } from './preferences-matrix'

/** A person's own notification settings: where they are reached, and what they want to receive. */
export function NotificationSettings({ signInEmail, onNotify = ignoreNotice }: { signInEmail?: string; onNotify?: Notify }) {
  return (
    <div className="space-y-6">
      <ContactsCard signInEmail={signInEmail} onNotify={onNotify} />
      <PreferencesMatrix onNotify={onNotify} />
    </div>
  )
